#!/usr/bin/env -S uv run --no-project --script
# /// script
# requires-python = ">=3.10"
# dependencies = []
# ///
"""Machine-local paired rerun of the seccomp perf harness on arm64.

Runs the 31 harness cases from benchmarks/docker/results/2026-11-16-compatible.json
against a before and an after build of `openshell-seccomp-perf`, each inside a
locked-down container of one pinned Docker image. Standard library only.

Default invocation from the repository root:

    uv run --no-project .cache/perf-rerun-arm64/run-harness.py --image <image id>
"""

from __future__ import annotations

import argparse
import datetime as _dt
import hashlib
import json
import os
import platform
import random
import re
import shutil
import signal
import statistics
import subprocess
import sys
import time
import uuid
from pathlib import Path
from typing import Any

SCHEMA_VERSION = 1
HARNESS_BINARY = "openshell-seccomp-perf"
CONTAINER_PREFIX = "perf-arm64-"
INVOCATION_TIMEOUT_SECONDS = 240
PROVIDER_FILE_PATH = "/run/openshell/providers/perf/config.toml"
ORDINARY_FILE_PATH = "/etc/passwd"
MIXED_FILE_CLASS = "file-open-read"
MIXED_CLASSES = {
    "mixed-file-tcp-connect": {MIXED_FILE_CLASS, "tcp-connect"},
    "mixed-file-tcp-stream": {MIXED_FILE_CLASS, "tcp-stream"},
}
FILE_PROTOCOLS = {"file-open-read", "file-open-close", "file-read"}
IMAGE_ID_RE = re.compile(r"^(sha256:)?[0-9a-f]{12,64}$")

# The exact 31 cases of harness.cases in 2026-11-16-compatible.json, in file order.
# (name, protocol, threads, iterations, provider_bytes)
CASES: list[tuple[str, str, int, int, int | None]] = [
    ("ordinary-open-read", "file-open-read", 1, 10000, None),
    ("provider-open-read-4096", "file-open-read", 1, 10000, 4096),
    ("provider-open-read-65536", "file-open-read", 1, 10000, 65536),
    ("tcp-connect", "tcp-connect", 1, 1000, None),
    ("tcp-stream", "tcp-stream", 1, 5000, None),
    ("ordinary-mixed-file-tcp-connect", "mixed-file-tcp-connect", 1, 1000, None),
    ("provider-mixed-file-tcp-connect", "mixed-file-tcp-connect", 1, 1000, 4096),
    ("ordinary-mixed-file-tcp-stream", "mixed-file-tcp-stream", 1, 2000, None),
    ("provider-mixed-file-tcp-stream", "mixed-file-tcp-stream", 1, 2000, 4096),
    ("ordinary-open-read", "file-open-read", 4, 10000, None),
    ("provider-open-read-4096", "file-open-read", 4, 10000, 4096),
    ("provider-open-read-65536", "file-open-read", 4, 10000, 65536),
    ("tcp-connect", "tcp-connect", 4, 1000, None),
    ("tcp-stream", "tcp-stream", 4, 5000, None),
    ("ordinary-mixed-file-tcp-connect", "mixed-file-tcp-connect", 4, 1000, None),
    ("provider-mixed-file-tcp-connect", "mixed-file-tcp-connect", 4, 1000, 4096),
    ("ordinary-mixed-file-tcp-stream", "mixed-file-tcp-stream", 4, 2000, None),
    ("provider-mixed-file-tcp-stream", "mixed-file-tcp-stream", 4, 2000, 4096),
    ("ordinary-open-read", "file-open-read", 16, 10000, None),
    ("provider-open-read-4096", "file-open-read", 16, 10000, 4096),
    ("provider-open-read-65536", "file-open-read", 16, 10000, 65536),
    ("tcp-connect", "tcp-connect", 16, 1000, None),
    ("tcp-stream", "tcp-stream", 16, 5000, None),
    ("ordinary-mixed-file-tcp-connect", "mixed-file-tcp-connect", 16, 1000, None),
    ("provider-mixed-file-tcp-connect", "mixed-file-tcp-connect", 16, 1000, 4096),
    ("ordinary-mixed-file-tcp-stream", "mixed-file-tcp-stream", 16, 2000, None),
    ("provider-mixed-file-tcp-stream", "mixed-file-tcp-stream", 16, 2000, 4096),
    ("ordinary-open-close", "file-open-close", 1, 10000, None),
    ("ordinary-existing-fd-read", "file-read", 1, 100000, None),
    ("provider-open-close", "file-open-close", 1, 10000, 4096),
    ("provider-existing-fd-read", "file-read", 1, 100000, 4096),
]
assert len(CASES) == 31


class HarnessError(Exception):
    """A failure that ends the run and is recorded in the output."""


class Interrupted(Exception):
    """SIGINT or SIGTERM arrived."""


# --------------------------------------------------------------------------- utilities


def utc_now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def run_capture(cmd: list[str], timeout: float = 30.0) -> tuple[int | None, str, str]:
    try:
        proc = subprocess.run(
            cmd, capture_output=True, text=True, timeout=timeout, check=False
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return None, "", f"{type(exc).__name__}: {exc}"
    return proc.returncode, proc.stdout, proc.stderr


def best_effort(cmd: list[str]) -> str | None:
    code, out, _ = run_capture(cmd)
    if code != 0:
        return None
    return out.strip()


def host_load() -> dict[str, Any]:
    load: dict[str, Any] = {}
    try:
        with open("/proc/loadavg", encoding="utf-8") as handle:
            fields = handle.read().split()
        load["loadavg"] = [float(fields[0]), float(fields[1]), float(fields[2])]
        load["runnable"] = fields[3]
    except (OSError, ValueError, IndexError):
        load["loadavg"] = None
    try:
        with open("/proc/stat", encoding="utf-8") as handle:
            for line in handle:
                if line.startswith("cpu "):
                    values = [int(v) for v in line.split()[1:]]
                    load["cpu_total"] = sum(values)
                    # idle + iowait
                    load["cpu_idle"] = values[3] + (values[4] if len(values) > 4 else 0)
                    break
    except (OSError, ValueError):
        load["cpu_total"] = None
        load["cpu_idle"] = None
    counts = {"rustc": 0, "cargo": 0}
    try:
        for entry in os.scandir("/proc"):
            if not entry.name.isdigit():
                continue
            try:
                with open(f"/proc/{entry.name}/comm", encoding="utf-8") as handle:
                    comm = handle.read().strip()
            except OSError:
                continue
            if comm in counts:
                counts[comm] += 1
    except OSError:
        pass
    load["rustc_processes"] = counts["rustc"]
    load["cargo_processes"] = counts["cargo"]
    load["rust_processes"] = counts["rustc"] + counts["cargo"]
    load["sampled_utc"] = utc_now()
    return load


def cpu_busy_percent(before: dict[str, Any], after: dict[str, Any]) -> float | None:
    try:
        total = after["cpu_total"] - before["cpu_total"]
        idle = after["cpu_idle"] - before["cpu_idle"]
    except (KeyError, TypeError):
        return None
    if total <= 0:
        return None
    return 100.0 * (total - idle) / total


def git_metadata(repo_root: Path) -> dict[str, Any]:
    def git(*args: str) -> str | None:
        return best_effort(["git", "-C", str(repo_root), *args])

    status = git("status", "--porcelain=v1", "--untracked-files=no")
    return {
        "commit": git("rev-parse", "HEAD"),
        "branch": git("rev-parse", "--abbrev-ref", "HEAD"),
        "describe": git("describe", "--always", "--dirty", "--tags"),
        "status_porcelain": status.splitlines() if status is not None else None,
        "dirty": bool(status) if status is not None else None,
    }


def build_metadata(bin_dir: Path, output_dir: Path) -> dict[str, Any]:
    cargo_env = {
        key: value
        for key, value in sorted(os.environ.items())
        if key.startswith(("CARGO", "RUSTFLAGS", "RUSTUP", "RUSTC"))
        and "TOKEN" not in key
        and "KEY" not in key
    }
    build_logs = {}
    for log in sorted(output_dir.glob("build-*.log")):
        try:
            build_logs[log.name] = {
                "sha256": sha256_file(log),
                "bytes": log.stat().st_size,
            }
        except OSError:
            continue
    return {
        "rustc_version": best_effort(["rustc", "--version", "--verbose"]),
        "cargo_version": best_effort(["cargo", "--version", "--verbose"]),
        "cargo_env": cargo_env,
        "build_logs": build_logs,
        "note": (
            "This runner does not build. It executes prebuilt "
            f"{HARNESS_BINARY} binaries from {bin_dir}/before and {bin_dir}/after. "
            "The rustc and cargo versions and CARGO*/RUSTFLAGS environment above "
            "describe the host at run time, not necessarily the build; see the "
            "build-*.log files recorded alongside for the build invocations."
        ),
    }


def docker_metadata(image: str) -> tuple[str, dict[str, Any]]:
    code, out, err = run_capture(["docker", "image", "inspect", image])
    if code != 0:
        raise HarnessError(f"docker image inspect {image} failed: {err.strip() or out.strip()}")
    try:
        inspected = json.loads(out)[0]
    except (json.JSONDecodeError, IndexError, TypeError) as exc:
        raise HarnessError(f"docker image inspect returned unexpected output: {exc}") from exc
    resolved_id = inspected.get("Id", "")
    wanted = image if image.startswith("sha256:") else f"sha256:{image}"
    if not resolved_id.startswith(wanted):
        raise HarnessError(
            f"--image must be a pinned image ID; {image!r} resolved to {resolved_id!r}"
        )
    config = inspected.get("Config") or {}
    trimmed = {
        "Id": resolved_id,
        "RepoTags": inspected.get("RepoTags"),
        "RepoDigests": inspected.get("RepoDigests"),
        "Created": inspected.get("Created"),
        "Architecture": inspected.get("Architecture"),
        "Variant": inspected.get("Variant"),
        "Os": inspected.get("Os"),
        "Size": inspected.get("Size"),
        "Config": {
            "User": config.get("User"),
            "WorkingDir": config.get("WorkingDir"),
            "Entrypoint": config.get("Entrypoint"),
            "Cmd": config.get("Cmd"),
        },
    }
    version_json = best_effort(["docker", "version", "--format", "{{json .}}"])
    version: Any = None
    if version_json:
        try:
            version = json.loads(version_json)
        except json.JSONDecodeError:
            version = version_json
    return resolved_id, {"image_inspect": trimmed, "docker_version": version}


def host_metadata() -> dict[str, Any]:
    uname = os.uname()
    cpu_model = None
    try:
        with open("/proc/cpuinfo", encoding="utf-8") as handle:
            for line in handle:
                if line.lower().startswith(("model name", "hardware", "cpu part")):
                    cpu_model = line.split(":", 1)[1].strip()
                    break
    except OSError:
        pass
    return {
        "arch": platform.machine(),
        "kernel_release": uname.release,
        "kernel_version": uname.version,
        "system": uname.sysname,
        "hostname_hash": hashlib.sha256(uname.nodename.encode()).hexdigest()[:16],
        "cpu_count": os.cpu_count(),
        "cpu_model": cpu_model,
        "python": sys.version,
    }


# --------------------------------------------------------------------------- cases


def case_key(case: dict[str, Any]) -> str:
    return f"{case['name']}@t{case['threads']}"


def build_cases(multiplier: float, filters: list[str]) -> list[dict[str, Any]]:
    cases = []
    for name, protocol, threads, iterations, provider_bytes in CASES:
        count = max(1, int(round(iterations * multiplier)))
        case = {
            "name": name,
            "protocol": protocol,
            "threads": threads,
            "iterations": count,
            "base_iterations": iterations,
            "warmup": max(100, count // 10),
            "provider_bytes": provider_bytes,
        }
        key = case_key(case)
        if filters and not any(f in key or f in protocol for f in filters):
            continue
        cases.append(case)
    return cases


def harness_args(case: dict[str, Any]) -> list[str]:
    args = [
        "--layer",
        "filtered",
        "--protocol",
        case["protocol"],
        "--landlock",
        "--concurrency",
        str(case["threads"]),
        "--iterations",
        str(case["iterations"]),
        "--warmup",
        str(case["warmup"]),
    ]
    if case["provider_bytes"] is not None:
        args += ["--provider-file", "--provider-file-bytes", str(case["provider_bytes"])]
    return args


def docker_command(container: str, image_id: str, binary: Path, case: dict[str, Any]) -> list[str]:
    return [
        "docker",
        "run",
        "--rm",
        "--name",
        container,
        "--network",
        "none",
        "--cap-drop",
        "ALL",
        "--security-opt",
        "no-new-privileges",
        "--user",
        "1000:1000",
        "--workdir",
        "/sandbox",
        "--mount",
        f"type=bind,src={binary},dst=/perf,readonly",
        "--entrypoint",
        "/perf",
        image_id,
        *harness_args(case),
    ]


def trial_order(cases: list[dict[str, Any]], trial: int) -> list[dict[str, Any]]:
    order = list(cases)
    random.Random(f"perf-rerun-arm64:{trial}").shuffle(order)
    return order


def variant_order(trial: int, pair_index: int) -> tuple[str, str]:
    return ("before", "after") if (trial + pair_index) % 2 == 0 else ("after", "before")


# --------------------------------------------------------------------------- validation


def parse_reports(stdout: str) -> list[dict[str, Any]]:
    reports = []
    for lineno, line in enumerate(stdout.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            report = json.loads(line)
        except json.JSONDecodeError as exc:
            raise HarnessError(f"stdout line {lineno} is not JSON: {exc}: {line[:200]!r}") from exc
        if not isinstance(report, dict):
            raise HarnessError(f"stdout line {lineno} is not a JSON object")
        reports.append(report)
    if not reports:
        raise HarnessError("harness printed no JSONL reports")
    return reports


def validate_reports(case: dict[str, Any], reports: list[dict[str, Any]]) -> None:
    protocol = case["protocol"]
    expected_classes = MIXED_CLASSES.get(protocol)
    expected_count = 2 if expected_classes else 1
    if len(reports) != expected_count:
        raise HarnessError(f"expected {expected_count} report(s), got {len(reports)}")
    seen_classes = set()
    for report in reports:
        for field in (
            "layer",
            "protocol",
            "concurrency",
            "landlock",
            "iterations",
            "operations_per_second",
            "latency_ns_p50",
            "latency_ns_p99",
        ):
            if field not in report:
                raise HarnessError(f"report missing field {field!r}")
        if report["layer"] != "filtered":
            raise HarnessError(f"report layer {report['layer']!r} != 'filtered'")
        if report["protocol"] != protocol:
            raise HarnessError(f"report protocol {report['protocol']!r} != {protocol!r}")
        if report["concurrency"] != case["threads"]:
            raise HarnessError(
                f"report concurrency {report['concurrency']!r} != {case['threads']}"
            )
        if report["landlock"] is not True:
            raise HarnessError("report landlock is not true")
        klass = report.get("class")
        if expected_classes:
            if klass not in expected_classes:
                raise HarnessError(f"unexpected mixed class {klass!r}")
            if klass in seen_classes:
                raise HarnessError(f"duplicate mixed class {klass!r}")
            seen_classes.add(klass)
            is_file = klass == MIXED_FILE_CLASS
        else:
            if klass is not None:
                raise HarnessError(f"unexpected class {klass!r} on a single-class report")
            # perf.rs reports total measured operations: per-worker iterations * workers.
            expected_iterations = case["iterations"] * case["threads"]
            if report["iterations"] != expected_iterations:
                raise HarnessError(
                    f"report iterations {report['iterations']} != {expected_iterations} "
                    f"({case['iterations']} x {case['threads']} workers)"
                )
            is_file = protocol in FILE_PROTOCOLS
        # perf.rs attaches provider_file_bytes only to file-class reports; the TCP
        # class of a managed mixed case omits it.
        expected_provider = case["provider_bytes"] if is_file else None
        if report.get("provider_file_bytes") != expected_provider:
            raise HarnessError(
                f"report provider_file_bytes {report.get('provider_file_bytes')!r} "
                f"!= {expected_provider!r} for {'file' if is_file else 'tcp'} report"
            )
        if is_file:
            expected_path = (
                PROVIDER_FILE_PATH if case["provider_bytes"] is not None else ORDINARY_FILE_PATH
            )
            if report.get("file_path") != expected_path:
                raise HarnessError(
                    f"report file_path {report.get('file_path')!r} != {expected_path!r}"
                )
        for field in ("latency_ns_p50", "latency_ns_p99", "operations_per_second"):
            value = report[field]
            if not isinstance(value, (int, float)) or value <= 0:
                raise HarnessError(f"report {field} is not a positive number: {value!r}")
    if expected_classes and seen_classes != expected_classes:
        raise HarnessError(f"mixed classes {sorted(seen_classes)} != {sorted(expected_classes)}")


# --------------------------------------------------------------------------- runner


class Runner:
    def __init__(self, args: argparse.Namespace) -> None:
        self.args = args
        self.output_path: Path = Path(args.output).resolve()
        self.summary_path = self.output_path.with_suffix(".md")
        self.bin_dir: Path = Path(args.bin_dir).resolve()
        self.repo_root = Path.cwd()
        self.current_container: str | None = None
        self.interrupted: int | None = None
        self.cases = build_cases(args.iterations_multiplier, args.case)
        self.result: dict[str, Any] = {}
        self.image_id = ""
        self.binaries: dict[str, Path] = {}

    # -- setup

    def prepare(self) -> None:
        if not self.cases:
            raise HarnessError("no cases match the --case filters")
        if not IMAGE_ID_RE.match(self.args.image):
            raise HarnessError(
                f"--image {self.args.image!r} is not a pinned image ID (sha256 hex or sha256:hex)"
            )
        if shutil.which("docker") is None:
            raise HarnessError("docker not found on PATH")
        for variant in ("before", "after"):
            binary = self.bin_dir / variant / HARNESS_BINARY
            if not binary.is_file():
                raise HarnessError(f"missing binary {binary}")
            if not os.access(binary, os.X_OK):
                raise HarnessError(f"binary is not executable: {binary}")
            self.binaries[variant] = binary
        self.image_id, docker_meta = docker_metadata(self.args.image)
        self.output_path.parent.mkdir(parents=True, exist_ok=True)
        self.result = {
            "schema_version": SCHEMA_VERSION,
            "complete": False,
            "started_utc": utc_now(),
            "finished_utc": None,
            "trials": self.args.trials,
            "iterations_multiplier": self.args.iterations_multiplier,
            "case_filters": list(self.args.case),
            "cases": self.cases,
            "image": self.image_id,
            "image_argument": self.args.image,
            "binaries": {
                variant: {"path": str(path), "sha256": sha256_file(path)}
                for variant, path in self.binaries.items()
            },
            "settings": {
                "layer": "filtered",
                "user": "1000:1000",
                "network": "none",
                "cap_drop": "ALL",
                "no_new_privileges": True,
                "docker_default_seccomp": True,
                "docker_default_apparmor": True,
                "landlock": True,
                "workdir": "/sandbox",
                "warmup_rule": "max(100, iterations // 10)",
                "invocation_timeout_seconds": INVOCATION_TIMEOUT_SECONDS,
            },
            "method": (
                f"{self.args.trials} paired trials; deterministic per-trial case shuffle "
                "seeded by trial; before/after order alternates per pair. Each invocation "
                "is a fresh --rm container of the pinned image running the mounted harness "
                "binary as /perf."
            ),
            "host": host_metadata(),
            "docker": docker_meta,
            "source": git_metadata(self.repo_root),
            "build": build_metadata(self.bin_dir, self.output_path.parent),
            "runner": {
                "path": str(Path(__file__).resolve()),
                "sha256": sha256_file(Path(__file__).resolve()),
                "argv": sys.argv,
            },
            "samples": [],
            "pairs": [],
            "error": None,
        }
        self.persist()

    # -- persistence

    def persist(self) -> None:
        tmp = self.output_path.with_name(self.output_path.name + ".tmp")
        with tmp.open("w", encoding="utf-8") as handle:
            json.dump(self.result, handle, indent=2)
            handle.write("\n")
        os.replace(tmp, self.output_path)
        try:
            summary = render_summary(self.result)
        except Exception as exc:  # summary must never block persistence
            summary = f"# Summary unavailable\n\n{type(exc).__name__}: {exc}\n"
        tmp_md = self.summary_path.with_name(self.summary_path.name + ".tmp")
        tmp_md.write_text(summary, encoding="utf-8")
        os.replace(tmp_md, self.summary_path)

    # -- signals

    def install_signal_handlers(self) -> None:
        signal.signal(signal.SIGINT, self._on_signal)
        signal.signal(signal.SIGTERM, self._on_signal)

    def _on_signal(self, signum: int, _frame: Any) -> None:
        self.interrupted = signum
        container = self.current_container
        if container:
            subprocess.run(
                ["docker", "rm", "-f", container],
                capture_output=True,
                text=True,
                check=False,
                timeout=30,
            )

    def remove_container(self, container: str) -> str:
        code, out, err = run_capture(["docker", "rm", "-f", container], timeout=60)
        return f"exit={code} stdout={out.strip()!r} stderr={err.strip()!r}"

    # -- one invocation

    def invoke(
        self, trial: int, pair_index: int, case: dict[str, Any], variant: str
    ) -> dict[str, Any]:
        container = f"{CONTAINER_PREFIX}{os.getpid()}-{uuid.uuid4().hex[:10]}"
        cmd = docker_command(container, self.image_id, self.binaries[variant], case)
        sample: dict[str, Any] = {
            "trial": trial,
            "pair_index": pair_index,
            "case": case,
            "variant": variant,
            "container": container,
            "binary_sha256": self.result["binaries"][variant]["sha256"],
            "harness_args": harness_args(case),
            "docker_args": cmd,
            "started_utc": None,
            "finished_utc": None,
            "wall_seconds": None,
            "exit_code": None,
            "timed_out": False,
            "reports": None,
            "stderr": None,
            "host_load_before": host_load(),
            "host_load_after": None,
            "host_cpu_busy_percent": None,
            "ok": False,
            "error": None,
        }
        self.current_container = container
        sample["started_utc"] = utc_now()
        start = time.monotonic()
        try:
            proc = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=INVOCATION_TIMEOUT_SECONDS,
                check=False,
            )
            stdout, stderr, exit_code = proc.stdout, proc.stderr, proc.returncode
        except subprocess.TimeoutExpired as exc:
            sample["wall_seconds"] = time.monotonic() - start
            sample["finished_utc"] = utc_now()
            sample["timed_out"] = True
            sample["stderr"] = _decode(exc.stderr)
            sample["stdout_partial"] = _decode(exc.stdout)
            # subprocess killed only the docker client; remove this container explicitly.
            sample["container_removal"] = self.remove_container(container)
            sample["host_load_after"] = host_load()
            sample["error"] = f"timed out after {INVOCATION_TIMEOUT_SECONDS}s"
            self.current_container = None
            return sample
        self.current_container = None
        sample["wall_seconds"] = time.monotonic() - start
        sample["finished_utc"] = utc_now()
        sample["host_load_after"] = host_load()
        sample["host_cpu_busy_percent"] = cpu_busy_percent(
            sample["host_load_before"], sample["host_load_after"]
        )
        sample["exit_code"] = exit_code
        sample["stderr"] = stderr
        if self.interrupted is not None:
            sample["error"] = f"interrupted by signal {self.interrupted}"
            sample["stdout_partial"] = stdout
            return sample
        if exit_code != 0:
            sample["error"] = f"harness exited with status {exit_code}"
            sample["stdout_partial"] = stdout
            return sample
        try:
            reports = parse_reports(stdout)
            validate_reports(case, reports)
        except HarnessError as exc:
            sample["error"] = f"invalid report: {exc}"
            sample["stdout_partial"] = stdout
            return sample
        sample["reports"] = reports
        sample["ok"] = True
        return sample

    # -- main loop

    def run(self) -> int:
        self.install_signal_handlers()
        self.prepare()
        total = self.args.trials * len(self.cases) * 2
        seq = 0
        try:
            for trial in range(self.args.trials):
                for pair_index, case in enumerate(trial_order(self.cases, trial)):
                    first, second = variant_order(trial, pair_index)
                    pair = {
                        "trial": trial,
                        "pair_index": pair_index,
                        "case_key": case_key(case),
                        "order": [first, second],
                        "sample_indices": {},
                    }
                    for variant in (first, second):
                        if self.interrupted is not None:
                            raise Interrupted()
                        seq += 1
                        sample = self.invoke(trial, pair_index, case, variant)
                        self.result["samples"].append(sample)
                        pair["sample_indices"][variant] = len(self.result["samples"]) - 1
                        self.progress(seq, total, sample)
                        if not sample["ok"]:
                            self.result["pairs"].append(pair)
                            self.persist()
                            if self.interrupted is not None:
                                raise Interrupted()
                            raise HarnessError(
                                f"trial {trial} {case_key(case)} {variant}: {sample['error']}"
                            )
                        self.persist()
                    self.result["pairs"].append(pair)
                    self.persist()
        except Interrupted:
            self.result["error"] = f"interrupted by signal {self.interrupted}"
            self.result["finished_utc"] = utc_now()
            self.persist()
            print(f"interrupted; partial output preserved at {self.output_path}", flush=True)
            return 130
        except HarnessError as exc:
            self.result["error"] = str(exc)
            self.result["finished_utc"] = utc_now()
            self.persist()
            print(f"error: {exc}", file=sys.stderr, flush=True)
            print(f"partial output preserved at {self.output_path}", flush=True)
            return 1
        expected_pairs = self.args.trials * len(self.cases)
        all_ok = (
            len(self.result["pairs"]) == expected_pairs
            and len(self.result["samples"]) == expected_pairs * 2
            and all(sample["ok"] for sample in self.result["samples"])
        )
        self.result["complete"] = bool(all_ok)
        self.result["finished_utc"] = utc_now()
        self.persist()
        print(
            f"done: {len(self.result['samples'])} invocations, complete={self.result['complete']}; "
            f"wrote {self.output_path} and {self.summary_path}",
            flush=True,
        )
        return 0 if all_ok else 1

    def progress(self, seq: int, total: int, sample: dict[str, Any]) -> None:
        case = sample["case"]
        key = case_key(case)
        wall = sample["wall_seconds"] or 0.0
        if sample["ok"]:
            parts = []
            for report in sample["reports"]:
                label = report.get("class") or report["protocol"]
                parts.append(
                    f"{label} p50={report['latency_ns_p50']}ns p99={report['latency_ns_p99']}ns "
                    f"ops={report['operations_per_second']:.0f}"
                )
            detail = "ok " + "; ".join(parts)
        else:
            detail = f"FAIL {sample['error']}"
        load = sample.get("host_load_before") or {}
        loadavg = load.get("loadavg")
        load_text = f"load1={loadavg[0]:.1f}" if loadavg else "load1=?"
        print(
            f"[{seq}/{total}] trial {sample['trial']} {key} {sample['variant']:<6} "
            f"{wall:6.2f}s {load_text} rust={load.get('rust_processes', '?')} {detail}",
            flush=True,
        )


def _decode(data: Any) -> str | None:
    if data is None:
        return None
    if isinstance(data, bytes):
        return data.decode("utf-8", errors="replace")
    return str(data)


# --------------------------------------------------------------------------- summary


def _median(values: list[float]) -> float | None:
    return statistics.median(values) if values else None


def _fmt_ns(value: float | None) -> str:
    return "-" if value is None else f"{value:,.0f}"


def _fmt_pct(value: float | None) -> str:
    return "-" if value is None else f"{value:+.1f}%"


def _rel(after: float, before: float) -> float:
    return 100.0 * (after - before) / before


def render_summary(result: dict[str, Any]) -> str:
    samples = result.get("samples", [])
    cases = result.get("cases", [])
    # rows[(case_key, class)] -> {trial: {variant: report}}
    rows: dict[tuple[str, str], dict[int, dict[str, dict[str, Any]]]] = {}
    for sample in samples:
        if not sample.get("ok") or not sample.get("reports"):
            continue
        key = case_key(sample["case"])
        for report in sample["reports"]:
            klass = report.get("class") or "-"
            rows.setdefault((key, klass), {}).setdefault(sample["trial"], {})[
                sample["variant"]
            ] = report

    host = result.get("host") or {}
    source = result.get("source") or {}
    lines = [
        "# Paired harness rerun summary",
        "",
        f"- Image `{result.get('image')}`, complete={result.get('complete')}",
        f"- Started {result.get('started_utc')}, finished {result.get('finished_utc')}",
        f"- Trials requested: {result.get('trials')}, cases: {len(cases)}, "
        f"invocations recorded: {len(samples)}, "
        f"failed: {sum(1 for s in samples if not s.get('ok'))}",
        f"- Iterations multiplier: {result.get('iterations_multiplier')}",
        f"- Source commit `{source.get('commit')}` dirty={source.get('dirty')}; "
        f"host {host.get('arch')} {host.get('kernel_release')}",
    ]
    if result.get("error"):
        lines.append(f"- Error: {result['error']}")
    lines += [
        "",
        "Latency columns are medians across trials of each variant's reported p50/p99 "
        "in nanoseconds. Change columns are the median across trials of the paired "
        "relative change (after vs before) in p50, p99, and operations per second. "
        "Negative latency change and positive throughput change favor `after`. "
        "`p50 improved` counts paired trials where after p50 < before p50.",
        "",
        "| Case | Class | Pairs | Before p50 | After p50 | Before p99 | After p99 | "
        "Δ p50 | Δ p99 | Δ ops/s | p50 improved |",
        "|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
    ]
    improved_total = 0
    pairs_total = 0
    ordered_keys = [case_key(c) for c in cases]

    def sort_key(item: tuple[str, str]) -> tuple[int, str]:
        key, klass = item
        index = ordered_keys.index(key) if key in ordered_keys else len(ordered_keys)
        return (index, klass)

    for key, klass in sorted(rows, key=sort_key):
        trials = rows[(key, klass)]
        before_p50: list[float] = []
        after_p50: list[float] = []
        before_p99: list[float] = []
        after_p99: list[float] = []
        d_p50: list[float] = []
        d_p99: list[float] = []
        d_ops: list[float] = []
        improved = 0
        pairs = 0
        for reports in trials.values():
            before, after = reports.get("before"), reports.get("after")
            if before:
                before_p50.append(before["latency_ns_p50"])
                before_p99.append(before["latency_ns_p99"])
            if after:
                after_p50.append(after["latency_ns_p50"])
                after_p99.append(after["latency_ns_p99"])
            if before and after:
                pairs += 1
                d_p50.append(_rel(after["latency_ns_p50"], before["latency_ns_p50"]))
                d_p99.append(_rel(after["latency_ns_p99"], before["latency_ns_p99"]))
                d_ops.append(
                    _rel(after["operations_per_second"], before["operations_per_second"])
                )
                if after["latency_ns_p50"] < before["latency_ns_p50"]:
                    improved += 1
        improved_total += improved
        pairs_total += pairs
        lines.append(
            f"| {key} | {klass} | {pairs} | {_fmt_ns(_median(before_p50))} | "
            f"{_fmt_ns(_median(after_p50))} | {_fmt_ns(_median(before_p99))} | "
            f"{_fmt_ns(_median(after_p99))} | {_fmt_pct(_median(d_p50))} | "
            f"{_fmt_pct(_median(d_p99))} | {_fmt_pct(_median(d_ops))} | {improved}/{pairs} |"
        )
    lines += [
        "",
        f"p50 improved in {improved_total} of {pairs_total} paired (case, class, trial) samples.",
        "",
    ]
    return "\n".join(lines)


# --------------------------------------------------------------------------- cli


def parse_args(argv: list[str]) -> argparse.Namespace:
    cwd = Path.cwd()
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument("--trials", type=int, default=9, help="paired trials (default 9)")
    parser.add_argument(
        "--output",
        default=str(cwd / ".cache" / "perf-rerun-arm64" / "harness.json"),
        help="JSON output path; a .md summary is written alongside",
    )
    parser.add_argument(
        "--image", required=True, help="pinned Docker image ID (sha256 hex or sha256:hex)"
    )
    parser.add_argument(
        "--bin-dir",
        default=str(cwd / ".cache" / "perf-rerun-arm64" / "bin"),
        help=f"directory holding before/{HARNESS_BINARY} and after/{HARNESS_BINARY}",
    )
    parser.add_argument(
        "--case",
        action="append",
        default=[],
        help="substring filter on case key (name@tN) or protocol; repeatable",
    )
    parser.add_argument(
        "--iterations-multiplier",
        type=float,
        default=1.0,
        help="scale every case's iteration count (warmup follows max(100, count // 10))",
    )
    args = parser.parse_args(argv)
    if args.trials < 1:
        parser.error("--trials must be at least 1")
    if args.iterations_multiplier <= 0:
        parser.error("--iterations-multiplier must be positive")
    return args


def main(argv: list[str]) -> int:
    args = parse_args(argv)
    runner = Runner(args)
    try:
        return runner.run()
    except HarnessError as exc:
        # Setup errors before the first persist land here.
        print(f"error: {exc}", file=sys.stderr, flush=True)
        if runner.result:
            runner.result["error"] = str(exc)
            runner.result["finished_utc"] = utc_now()
            runner.persist()
        return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
